CREATE TABLE audit_events (
  id text PRIMARY KEY,
  workspace_id text NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  event_type text NOT NULL,
  action text NOT NULL,
  outcome text NOT NULL,
  actor_type text NOT NULL,
  actor_id text NOT NULL,
  user_id text,
  agent text,
  model text,
  request_id text NOT NULL,
  resource_type text,
  resource_id text,
  context_id text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT audit_events_outcome CHECK (outcome IN ('success', 'denied', 'error')),
  CONSTRAINT audit_events_actor_type
    CHECK (actor_type IN ('user', 'service_principal', 'system')),
  CONSTRAINT audit_events_metadata_object CHECK (jsonb_typeof(metadata) = 'object'),
  CONSTRAINT audit_events_agent_identity CHECK (
    agent IS NULL OR (model IS NOT NULL AND user_id IS NOT NULL)
  )
);
CREATE INDEX audit_events_workspace_time_idx
  ON audit_events (workspace_id, occurred_at DESC);
CREATE INDEX audit_events_workspace_resource_idx
  ON audit_events (workspace_id, resource_type, resource_id);
CREATE INDEX audit_events_request_idx ON audit_events (request_id);

ALTER TABLE audit_events
  DROP CONSTRAINT audit_events_agent_identity,
  ADD CONSTRAINT audit_events_agent_identity CHECK (
    (agent IS NULL AND model IS NULL)
    OR (agent IS NOT NULL AND model IS NOT NULL)
  );

COMMENT ON CONSTRAINT audit_events_agent_identity ON audit_events IS
  'Caller-declared agent and model are paired; authenticated user identity remains nullable for organization-owned service principals.';
ALTER TABLE audit_events
  ADD COLUMN retention_class text NOT NULL DEFAULT 'permanent';

UPDATE audit_events
   SET retention_class = 'detailed_read_90d'
 WHERE metadata->>'retentionClass' = 'detailed_read_90d';

ALTER TABLE audit_events
  ADD CONSTRAINT audit_events_retention_class
  CHECK (retention_class IN ('detailed_read_90d', 'permanent'));

CREATE INDEX audit_events_retention_idx
  ON audit_events (retention_class, occurred_at, id);
CREATE INDEX audit_events_workspace_filters_idx
  ON audit_events (
    workspace_id,
    action,
    outcome,
    occurred_at DESC,
    id DESC
  );
CREATE INDEX audit_events_workspace_skill_time_idx
  ON audit_events (
    workspace_id,
    (metadata->>'skillId'),
    occurred_at DESC,
    id DESC
  );
CREATE INDEX audit_events_workspace_context_time_idx
  ON audit_events (workspace_id, context_id, occurred_at DESC, id DESC);
CREATE INDEX audit_events_workspace_agent_model_idx
  ON audit_events (workspace_id, agent, model, occurred_at DESC, id DESC);

DROP TRIGGER audit_events_immutable ON audit_events;

CREATE OR REPLACE FUNCTION skillplane_protect_audit_event()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND current_setting('skillplane.audit_retention_job', true) = 'enabled'
     AND OLD.retention_class = 'detailed_read_90d'
     AND OLD.occurred_at < now() - interval '90 days' THEN
    RETURN OLD;
export function skillCreate(runtime: McpToolRuntime, input: SkillCreateInput) {
  return executeMutationTool(
    runtime,
    "skill_create",
    input.caller,
    async (execution) => {
      const resolved = await resolveWorkspaceForWrite(
        runtime,
        execution,
        input.workspace,
      );
      const files = new Map<string, Uint8Array>([
        ["SKILL.md", new TextEncoder().encode(input.instructions)],
      ]);
      for (const asset of input.assets) {
        files.set(
          asset.path,
          asset.content !== undefined
            ? new TextEncoder().encode(asset.content)
            : decodeBase64(asset.contentBase64 ?? ""),
        );
      }
      const canonical = await canonicalizeBundleFiles({
        skill: {
          formatVersion: 1,
          name: input.name,
          slug: input.slug,
          description: input.description,
          tags: input.tags,
          entrypoint: "SKILL.md",
        },
        files,
      });
      const created = await runtime.services.skillService.create({
        workspaceId: resolved.workspace.id,
        principal: resolved.principal,
        archiveBytes: canonical.bytes,
        visibility: input.visibility,
        idempotencyKey: input.idempotencyKey,
        requestId: execution.requestId,
        auditContext: mutationAuditContext(runtime, input.caller),
      });
      execution.setScope({
        resourceType: "skill",
        resourceId: created.skill.id,
        skillId: created.skill.id,
        versionId: created.version.id,
        versionDigest: created.version.digest,
      });
      const output: SkillCreateOutput = {
        requestId: execution.requestId,
        skill: lifecycleSkill(created.skill, resolved.workspace.slug),
        version: lifecycleVersion(created.version),
      };
      return { output };
    },
  );
}

export function skillVisibilityUpdate(
  runtime: McpToolRuntime,
  input: SkillVisibilityUpdateInput,
) {
  return executeMutationTool(
    runtime,
    "skill_visibility_update",
    input.caller,
    async (execution) => {
      const skill = await resolveSkill(runtime, execution, input.skill, {
        action: "skills:write",
        allowPublic: false,
        includeArchived: true,
      });
      const updated = await runtime.services.skillService.setVisibility({
        skillId: skill.id,
        principal: principal(skill.principal),
        visibility: input.visibility,
      outputSchema: contextNotesListOutputSchema,
      annotations: READ_ONLY_ANNOTATIONS,
    },
    (input) => contextNotesList(runtime, input),
  );

  server.registerTool(
    "skill_amend",
    {
      title: "Amend a skill",
      description:
        "Create one immutable, replay-safe skill amendment from an exact current base using digest-checked add, replace, or delete operations, structured learning evidence, and the skill's review or trusted auto-publication policy.",
      inputSchema: skillAmendInputSchema,
      outputSchema: skillAmendOutputSchema,
      annotations: MUTATION_ANNOTATIONS,
    },
    (input) => skillAmend(runtime, input),
  );

  server.registerTool(
    "skill_create",
    {
      title: "Create a skill",
      description:
        "Create one authorized skill and immutable published 1.0.0 version from a bounded canonical file set with caller attribution, durable audit, and replay-safe idempotency.",
      inputSchema: skillCreateInputSchema,
      outputSchema: skillCreateOutputSchema,
      annotations: MUTATION_ANNOTATIONS,
    },
    (input) => skillCreate(runtime, input),
  );

  server.registerTool(
    "skill_visibility_update",
    {
      title: "Update skill visibility",
      description:
        "Change authorized skill visibility using the exact previously observed updatedAt value, durable audit, and replay-safe idempotency.",
      inputSchema: skillVisibilityUpdateInputSchema,
      outputSchema: skillLifecycleMutationOutputSchema,
      annotations: MUTATION_ANNOTATIONS,
    },
    (input) => skillVisibilityUpdate(runtime, input),
  );

  server.registerTool(
    "skill_archive",
    {
      title: "Archive a skill",
      description:
        "Archive one authorized skill while preserving immutable versions and contexts, using optimistic concurrency and replay-safe idempotency.",
      inputSchema: skillStateMutationInputSchema,
      outputSchema: skillLifecycleMutationOutputSchema,
      annotations: MUTATION_ANNOTATIONS,
    },
    (input) => skillArchive(runtime, input),
  );

  server.registerTool(
    "skill_restore",
    {
      title: "Restore a skill",
      description:
        "Restore one authorized archived skill using optimistic concurrency, durable audit, and replay-safe idempotency.",
      inputSchema: skillStateMutationInputSchema,
      outputSchema: skillLifecycleMutationOutputSchema,
    case "skills_search":
    case "skill_asset_retrieve":
    case "skill_versions_list":
    case "skill_versions_diff":
    case "skill_candidates_list":
    case "skill_amendment_policy_get":
      return ["skills:read"];
    case "skill_retrieve": {
      const args = record.params.arguments;
      const hasContext =
        args !== null &&
        args !== undefined &&
        typeof args === "object" &&
        !Array.isArray(args) &&
        "context" in args;
      return hasContext ? ["contexts:read", "skills:read"] : ["skills:read"];
    }
    case "context_get":
    case "contexts_list":
    case "context_knowledge_history":
    case "context_notes_list":
      return ["contexts:read"];
    case "skill_amend":
      return ["skills:amend"];
    case "skill_create":
    case "skill_visibility_update":
    case "skill_archive":
    case "skill_restore":
      return ["skills:write"];
    case "skill_candidate_approve":
    case "skill_candidate_reject":
    case "skill_amendment_policy_update":
      return ["skills:publish"];
    case "context_create":
    case "context_update":
    case "context_archive":
    case "context_restore":
    case "context_knowledge_update":
    case "context_note_upsert":
      return ["contexts:write"];
    default:
      return [];
  }
}

